window.HA={"sc":{"note":"The Heat Assembly: numbers and rules of play for /heat-assembly/. Every magnitude here is a game mechanic, not a measurement. The words live in tools/heat-assembly-text.js; the rules that use these numbers live in heat-assembly/engine.js. Changing a number here can change the lesson: run node tools/check-heat-assembly.js, whose design guards fail if one path starts to help everyone.","v":1,"budget":3,"rota":2,"reserve":{"max":3,"keep":1},"prices":{"cover":1,"relief":1,"water":1,"evening":1,"hire":2},"reliefBlocks":{"2":2,"3":1,"4":2},"hireBlocks":1,"people":[{"id":"tara","kind":"queue","start":2,"own":2},{"id":"jeevan","kind":"dayrate","start":2,"own":0},{"id":"noor","kind":"home","start":1,"own":0},{"id":"kiran","kind":"stall","start":3,"own":1},{"id":"hira","kind":"mobility","start":2,"own":1}],"roles":["workers","market","municipal","coordinator"],"staff":[{"id":"caretaker","cap":{"day":2,"night":1},"services":["hall","child","water"]},{"id":"attendant","cap":{"day":1,"night":1},"services":["hall","child","water"]}],"extraServices":["hall","water"],"rounds":[{"n":1,"kind":"forecast","blocks":[]},{"n":2,"kind":"day","blocks":["midday","afternoon"]},{"n":3,"kind":"night","blocks":["evening","morning"]},{"n":4,"kind":"day","blocks":["midday","afternoon"]}],"blockServices":{"midday":["hall","child","water"],"afternoon":["hall","child","water"],"evening":["hall"],"morning":["child","water"]},"steps":[{"round":1,"t":"queue"},{"round":1,"t":"money"},{"round":2,"t":"predict"},{"round":2,"t":"roster"},{"round":2,"t":"prep"},{"round":3,"t":"evening"},{"round":3,"t":"roster"},{"round":3,"t":"prep"},{"round":4,"t":"hire"},{"round":4,"t":"roster"},{"round":4,"t":"cover"}],"consents":{"queue":["market","workers"],"coverRota":["workers","market"],"coverPaid":["municipal","market"],"relief":["municipal","coordinator"],"water":["municipal","coordinator","market"],"evening":["municipal","coordinator"],"hire":["municipal","coordinator"],"roster":["coordinator"]},"sources":[{"id":"piece-rate","record":"ACTION_SETTINGS","card":"work:breaks","field":"stops"},{"id":"cannot-leave","record":"ACTION_SETTINGS","card":"neighbourhoods:centres","field":"stops"},{"id":"station","record":"ACTION_SETTINGS","card":"work:station","field":"stops"},{"id":"hot-day-cost","record":"HEAT_WEEK","list":"evidence","index":0},{"id":"vendors","record":"HEAT_WEEK","list":"evidence","index":1},{"id":"cut-hours","record":"HEAT_WEEK","list":"evidence","index":2},{"id":"early-money","record":"ACTION_SETTINGS","card":"summer:ready","field":"stops"},{"id":"in-time","record":"PLACE_SIM","list":"evidence","index":3},{"id":"no-health-claim","record":"LEVERS","lever":"coolingcentres","list":"watch","index":0}]},"text":{"title":"The Heat Assembly","kicker":"A game for one person or a group","lede":"A shaded hall is open beside the market, and almost nobody who needs it can use it. Take a seat at the table, make agreements over four rounds of heat, and see who could take a break, whose earnings changed and why.","fictional":"Fictional","fictionalNote":"The market town, the people and the events here are made up. The direction of each relationship comes from the sources listed below; every number in the game is a game mechanic, not a measurement.","objective":"By the end, you could explain from your own game how a decision about pay, care, staffing or authority changed who could use heat protection.","time":"About 10 minutes on your own, or 15 to 20 minutes around a table.","opening":{"clock":"11:40 a.m.","place":"A made-up market town on a river plain","lines":["The public hall beside the market is open, shaded and paid for. It is nearly empty.","Out in the loading lane, porters wait in a queue for the next truck. Leaving the queue means going to the back of it, and maybe losing the next paid load.","Across the square, a caretaker is due at the childcare centre this afternoon. The same caretaker is the only person who can keep the hall open.","A forecast has just come in: a hot day tomorrow, a hot night after it, and a second heat alert to follow."]},"modes":{"solo":{"label":"Play on my own","text":"Take one seat at the table. The other three answer by fixed, visible rules, and say what would change their answer."},"group":{"label":"Play together on one device","text":"Pass the device round so each person reads one role card in private, then decide together on a shared screen."}},"people":{"tara":{"name":"Tara","tag":"Queue porter, paid per load","pay":"Paid for each load carried. A place in the queue is the only security in the job.","care":"No one at home depends on Tara during the day.","needs":"A midday break in the hall, without losing a place in the queue."},"jeevan":{"name":"Jeevan","tag":"Porter on a day rate","pay":"Hired by one trader for the whole day at a fixed rate, so a break costs Jeevan no earnings.","care":"Free to rest whenever the hall is open.","needs":"Any open hour in the hall."},"noor":{"name":"Noor","tag":"Home-based stitcher, cares for a child of three","pay":"Paid for each piece finished at home. The hours the childcare centre is open are the hours Noor can work.","care":"Looks after a child of three.","needs":"Childcare at midday and in the afternoon; nothing on the table cools Noor's home in the day."},"kiran":{"name":"Kiran","tag":"Stall holder with a fixed pitch","pay":"Sells from a pitch Kiran holds. A neighbour can mind the stall in the afternoon lull, not at the midday peak.","care":"Lives in a solid house that cools at night.","needs":"An afternoon break in the hall."},"hira":{"name":"Hira","tag":"Older tea seller at the loading bay","pay":"Earns from daily sales at the bay.","care":"Cannot walk to the hall in the heat; a rickshaw costs a day's money.","needs":"Water and shade at the bay itself."}},"roles":{"workers":{"name":"Workers' representative","resource":"Two rota days for the whole game: a day when a porter on a fixed rate covers the queue so others can rest.","constraint":"On a rota day, Jeevan covers the loads at midday, so Jeevan can rest only in the afternoon.","fact":"Leaving the queue costs a porter paid per load about two loads. A porter on a day rate loses nothing.","can":"Organise a relief rota, propose a change to the queue, or turn down an arrangement workers could not use."},"market":{"name":"Market association","resource":"The loading order.","constraint":"Changing the queue rule takes one round's notice, and the loads still have to move: every round the rule runs, someone has to cover them.","fact":"Trucks run late on hot days, so midday is the heaviest unloading.","can":"Keep a porter's place in the queue, or negotiate cover for the loads."},"municipal":{"name":"Municipal officer","resource":"An operating budget of three units for the whole game, and authority over the public hall.","constraint":"Staff money approved now buys cover next round. Hiring on the day costs twice as much and gives less.","fact":"The hall's funding covers the building, not extra staff hours.","can":"Release budget, authorise evening use of the hall, or approve spending ahead for a later round."},"coordinator":{"name":"Neighbourhood services coordinator","resource":"A caretaker who can work two blocks a day (one at night) and an attendant who can work one.","constraint":"One person, one service, one block at a time. Whoever works the evening is not there next morning.","fact":"Noor's paid hours are the childcare hours. Hira cannot walk to the hall.","can":"Set the timetable for the hall, the water point and childcare, and say who loses access when it changes."}},"services":{"hall":"The hall","child":"Childcare","water":"Water point at the bay"},"blocks":{"midday":"midday","afternoon":"afternoon","evening":"evening","morning":"next morning"},"staff":{"caretaker":"Caretaker","attendant":"Attendant","relief":"Relief staff","hired":"Same-day hire"},"rounds":{"1":{"name":"The forecast","time":"11:40 a.m., the day before the heat"},"2":{"name":"The first hot market day","time":"Midday and afternoon"},"3":{"name":"The hot night and the morning after","time":"Evening and next morning"},"4":{"name":"The second heat alert","time":"Midday and afternoon"}},"steps":{"queue":{"h":"Tara is in the queue. Change the rule?","intro":"The hall is open, but Tara will not leave the queue: going to the back costs about two loads. The market association could keep a place for anyone who takes a break, if the loads keep moving.","reveal":["workers","market"],"options":{"rota":{"label":"Keep places, and let the workers' rota cover the loads","cost":"Uses one of two rota days. Jeevan covers at midday tomorrow."},"paid":{"label":"Keep places, and pay for cover","cost":"Uses one unit of the budget of three."},"none":{"label":"Keep places, with no one named to cover","cost":"Costs nothing, if the market association agrees."},"wait":{"label":"Leave the queue as it is for now","cost":"Costs nothing today. A change later needs a round's notice, so it could not run tomorrow."}}},"money":{"h":"The forecast is in. Spend now, or hold?","intro":"Money approved today buys relief staff who arrive tomorrow. A water point at the bay would reach Hira, who cannot walk to the hall. Each unit spent now is a unit that is not there for the hot night or the second alert.","reveal":["municipal"],"options":{"relief":{"label":"Relief staff for tomorrow (1 unit)","cost":"Two extra blocks of hall or water cover tomorrow, not childcare."},"water":{"label":"A water point at the loading bay (1 unit)","cost":"Usable from tomorrow, when someone staffs it."}}},"predict":{"h":"Before the day starts: who do you expect will be able to take a break in a cool place?","intro":"Choose everyone you expect. At the end, your expectation sits beside what happened.","notSure":"Not sure"},"roster":{"h":"Set the timetable","intro":"Each person can work one service in each block. Every block given to the hall is a block not given to childcare or water.","reveal":["coordinator"],"closed":"Closed","who":"Who it reaches"},"prep":{"h":"Plan ahead","intro":"Decisions now land next round.","queue":{"label":"Agree the queue rule now, to run from next round","cost":"Costs nothing to agree. On a hot day it still needs cover for the loads."},"relief":{"label":"Approve relief staff for next round (1 unit)","cost":"Lands next round: two blocks on a hot day, one at night."}},"evening":{"h":"Open the hall in the evening?","intro":"Homes stay hot after dark. Opening the hall in the evening needs the officer's authority, one unit, and someone on the evening block, who then cannot work the next morning.","on":{"label":"Open the hall in the evening (1 unit)","cost":"A cool evening for anyone who can get there; a person off the morning shift."},"off":{"label":"Keep the hall closed at night","cost":"Keeps the unit and the morning shift."}},"hire":{"h":"The second alert. Hire on the day?","intro":"Staff approved earlier arrive today. Hiring now costs two units and gives one block.","on":{"label":"Hire one person for one block today (2 units)","cost":"Hall or water only."},"off":{"label":"Work with the staff already here","cost":"Keeps the budget."}},"cover":{"h":"Who covers the loads today?","intro":"The queue rule only helps if the loads keep moving while someone rests.","options":{"rota":{"label":"The workers' rota covers","cost":"Uses a rota day. Jeevan covers at midday."},"paid":{"label":"Paid cover","cost":"Uses one unit."},"none":{"label":"No cover today","cost":"Places are not kept today."}}}},"replies":{"market-needs-cover":"The market association can agree once the loads are covered: name a rota day or one unit of paid cover.","market-no-rule":"There is no queue rule to cover yet. Agree the rule first; it runs from the round after.","market-queue-ok":"The market association agrees: places are kept while the loads keep moving.","market-ok":"The market association agrees.","workers-no-rota":"The rota days are used up. Paid cover would work instead.","workers-hall-closed":"Workers could not use it: the hall has no one on at midday, so a kept place leads nowhere. Staff the hall at midday first.","workers-ok":"The workers' representative agrees.","municipal-funds":"The budget has {left} left and this needs {need}. Dropping something else, or approving earlier next time, would free it.","municipal-evening":"The officer authorises evening use of the hall.","municipal-ok":"The officer releases the money.","coordinator-evening":"The coordinator agrees, and says whoever works the evening is off next morning.","coordinator-roster":"The coordinator agrees to the timetable.","coordinator-ok":"The coordinator agrees.","ok":"Agreed."},"errors":{"consent":"Someone whose agreement it needs has not agreed yet.","funds":"There is not enough budget left for this.","rota":"The rota days are used up.","over-cap":"One person cannot work that many blocks.","service-twice":"Two people are on the same service in the same block.","no-water-point":"There is no water point at the bay yet.","no-evening-hours":"The hall has no evening hours agreed.","hall-closed-midday":"The hall has no one on at midday, so a kept place leads nowhere.","no-queue-rule":"There is no queue rule running yet.","needs-cover":"The loads need someone to cover them.","wrong-step":"That decision belongs to another moment in the game.","already-agreed":"The queue rule is already agreed.","wrong-block":"That block is not part of this round.","wrong-service":"That person cannot run that service in that block.","roster-shape":"The timetable could not be read.","no-such-staff":"There is no such person on the roster this round.","bad-option":"That option is not on the table.","finished":"The game has finished."},"results":{"break":"Took a break in a cool place","own":"Took a break, at a cost to the household","none":"No break","home":"Stayed home","nocool":"No cool place reached"},"constraints":{"hall-midday-open":"The hall was open at midday.","hall-midday-closed":"The hall was closed at midday, when Tara's break falls.","hall-afternoon-open":"The hall was open in the afternoon.","hall-afternoon-closed":"The hall was closed in the afternoon.","hall-open":"The hall was open.","hall-closed":"The hall was closed.","place-kept":"The queue rule kept Tara's place.","cover-rota":"The workers' rota covered the loads.","cover-paid":"Paid cover kept the loads moving.","no-rule":"No queue rule was running, so leaving meant going to the back of the queue.","no-cover":"The queue rule was agreed but no one covered the loads today, so places were not kept.","paid-own-way":"Going cost a day's money or more, paid from the household's reserve.","reserve-too-low":"The household's reserve was too low to pay that cost and still get through the week.","covering-midday":"Jeevan was covering the loads at midday for the rota.","day-rate":"A day rate means a break costs Jeevan nothing.","no-daytime-reach":"Nothing on the table reaches a home in the daytime.","child-midday-open":"Childcare was open at midday.","child-midday-closed":"Childcare was closed at midday, so Noor could not work then.","child-afternoon-open":"Childcare was open in the afternoon.","child-afternoon-closed":"Childcare was closed in the afternoon, so Noor could not work then.","child-morning-open":"Childcare was open the next morning.","child-morning-closed":"Childcare was closed the next morning, so Noor could not work then.","neighbour-covers":"A neighbour minds Kiran's stall in the afternoon lull.","shut-at-peak":"A midday break means shutting the stall at the busiest hour.","water-open":"Someone was on the water point at the bay.","water-morning-open":"Someone was on the water point in the morning.","water-unstaffed":"The water point was there, but no one was on it.","no-water-point":"There was no water point at the bay.","at-the-bay":"Hira did not have to leave the bay.","rickshaw":"Reaching the hall meant a rickshaw, at a day's money.","evening-open":"The hall was open in the evening.","evening-unstaffed":"Evening hours were agreed and paid for, but no one was on the evening block, so the hall stayed shut.","no-evening":"The hall did not open in the evening.","cool-evening":"A cool evening let Tara recover some ground.","hot-room":"Tara spent the night in a hot room.","cooler-house":"Kiran's house cools at night."},"decisions":{"queue":"The decision on the queue rule","cover":"The decision on who covers the loads","roster":"The timetable for this round","evening":"The decision on evening hours","water":"The decision to build a water point"},"money":{"zero":"nothing","one":"1 day's money","many":"{n} days' money"},"reserve":"Household reserve","reserveNote":"Days of money a household can draw on, from 0 to 3 (a game mechanic).","ledger":{"person":"Person","what":"What happened","earn":"Earnings","reserve":"Reserve after","service":"Service","funded":"Funded","open":"Open","usable":"Used by","left":"Left after this round","budget":"Budget","rota":"Rota days","yes":"Yes","no":"No","none":"No one"},"why":"Why did this happen?","assumptions":[{"id":"units","text":"Budget, rota days and staff blocks are counted in simple game units, not money or hours from any real place."},{"id":"reserve","text":"Simplifying assumption: each household has a reserve of 0 to 3 days of money. Losing a day's earnings lowers it by one. Someone pays their own way to a break only if at least one day remains afterwards, so a loss now makes the next break harder, which can mean a further loss. A loss when the reserve is already empty is counted as a day the household could not cover."},{"id":"night","text":"A cool evening adds one day to the reserve of someone who spends it in the hall, standing in for recovering ground before the next day; a solid house does the same for Kiran."},{"id":"delay","text":"Money approved ahead buys staff one round later; hiring on the day costs twice as much and gives less. A queue rule agreed now runs from the next round."},{"id":"no-health","text":"The game counts breaks, earnings and reserves. It does not predict illness or death, and a break in the hall is not a measured health benefit."}],"sourcesIntro":"The direction of each relationship comes from evidence already on Common Shade. The sizes are the game's own.","grounds":{"piece-rate":"Why a break costs a porter paid per load more than one on a day rate.","cannot-leave":"Why an open hall can stay unusable for someone who cannot leave work.","station":"The same limit for worker cooling stations.","hot-day-cost":"Why a hot day without protection lowers earnings.","vendors":"Why traders lose income in a heatwave.","cut-hours":"Why informal workers cut hours in the heat.","early-money":"Why spending that starts when the heat does arrives late.","in-time":"Why money helps most when it arrives in time.","no-health-claim":"Why the game makes no claim about health outcomes."},"end":{"h":"How the four rounds ended, person by person","intro":"There is no score. Each line is what happened to one person.","expect":"What you expected","expectedYes":"You expected a break in a cool place on the first hot day.","expectedNo":"You did not expect a break in a cool place on the first hot day.","matched":"It happened as you expected.","differed":"It did not happen as you expected.","replayH":"Play the first hot day again","replayText":"Same weather, same budget, same choices up to the timetable on the first hot day. Change the timetable and play on.","replay":"Replay from the first hot day's timetable","compareH":"Two endings, side by side","compareA":"First ending","compareB":"Second ending","changed":"Different for: {names}.","unchanged":"Nobody's outcome changed. Try a timetable that moves the hall, childcare or water.","blindSpot":"No arrangement in this game cools Noor's home in the daytime. In a real place, that would be the next agreement to look for.","question":"In your own market, workplace or neighbourhood, who could change the equivalent of the queue rule?","suggestH":"Suggest a change","suggestText":"What would you have put on the table? It goes into your summary as an open question; the game does not play it out.","copy":"Copy a summary of this game","copied":"Summary copied","restart":"Start a new game","plan":"Carry the actions behind this game into a plan","explore":"Where this sits on the site"},"ui":{"start":"Start","next":"Next","agree":"Agree","decline":"Decline","propose":"Put it to the table","revise":"Change the proposal","confirm":"Confirm","you":"You","needsAgreement":"Needs agreement from","notAgreedBy":"Not agreed yet by","agreed":"Agreed","notAgreed":"Not agreed","notNeeded":"Not needed","pickRole":"Choose your seat","passTo":"Pass the device to the {role}","show":"Show my card","hide":"Hide and pass on","allRead":"Everyone has read their card","budget":"Budget","rota":"Rota days","staffLeft":"Staff blocks","round":"Round {n} of 4","continue":"Continue","changeFrom":"Change from here","readOnly":"This decision is already made. Going back shows it as it was.","stale":"A saved game from an older version could not be opened, so a new game has started.","playHere":"Play the first decision here","loading":"Loading the game","loadFailed":"The game could not load. The full game is on its own page.","open":"Open the full game","fullscreen":"Continue on the game's own page"},"links":[["/shared-heat/","This market town through a whole season"],["/actions/#heatrules","Heat-safe work"],["/actions/#coolingcentres","Cooling centres and check-ins"],["/actions/#heatcash","Income protection in heatwaves"],["/#informal","On the map: informal work in the heat"],["/#lost","On the map: lost earnings"],["/#care","On the map: care work"],["/together/","Make it work together"],["/a-week-in-the-heat/","A week in the heat"]],"plan":["work:breaks","neighbourhoods:centres","work:station","work:income","summer:ready"]},"sources":[{"id":"piece-rate","text":"Piece-rate pay and fixed deadlines that make stopping cost money, and no inspection.","label":"NUS Project HeatSafe, 2024","url":"https://medicine.nus.edu.sg/wp-content/uploads/2024/03/PRESS-RELEASE_Project-HeatSafe-18MAR2024-FOR-IMMEDIATE-RELEASE.pdf"},{"id":"cannot-leave","text":"A cooled building nobody can reach, open at the wrong hours, or a worker who cannot leave work to use it.","label":"US Centers for Disease Control and Prevention, in the GHHIN resource library","url":"https://heathealth.info/wp-content/uploads/cdc_47657_DS1-compressed-1.pdf"},{"id":"station","text":"A station nobody can leave work to use, or one that closes when the day is hottest.","label":"People’s Courage International, 2025: emergency response to the heatwave crisis in South and Southeast Asia","url":"https://www.peoplescourageinternational.org/pdfs/Emergency%20response%20to%20heat%20wave%20crisis%20in%20South%20and%20Southeast%20Asia.pdf"},{"id":"hot-day-cost","text":"In Singapore, a study of 355 workers found each hot day cost a median S$21, about 24% of a day’s pay.","label":"NUS Project HeatSafe, 2024","url":"https://medicine.nus.edu.sg/wp-content/uploads/2024/03/PRESS-RELEASE_Project-HeatSafe-18MAR2024-FOR-IMMEDIATE-RELEASE.pdf"},{"id":"vendors","text":"Of 721 Delhi street vendors surveyed in 2024, 80% saw fewer customers during heatwaves and 49% lost income.","label":"Greenpeace India and National Hawkers Federation, 2024","url":"https://www.greenpeace.org/india/en/press/16737/new-report-by-greenpeace-india-and-national-hawkers-federation-reveals-harsh-heatwave-toll-on-street-vendors/"},{"id":"cut-hours","text":"In Bangkok, nearly 80% of informal workers surveyed had cut their hours because of heat.","label":"WIEGO and HomeNet Thailand, 2025","url":"https://www.wiego.org/wp-content/uploads/2025/10/WIEGO-Policy-Brief-33-Climate-Change-and-Heat-Stress.pdf"},{"id":"early-money","text":"Procurement that starts when the heat does.","label":"The Hitavada, 11 May 2026","url":"https://www.thehitavada.com//Encyc/2026/5/11/green-nets-at-city-squares-relief-measure-or-another-half-planned-half-planned-civic-experiment.html"},{"id":"in-time","text":"Social protection can cushion the income workers lose to extreme heat, if it is designed to arrive in time.","label":"ILO: addressing the impacts of extreme heat through social protection","url":"https://www.ilo.org/resource/article/addressing-impacts-extreme-heat-through-social-protection"},{"id":"no-health-claim","text":"A 2025 review found no study that measured health outcomes for people using cooling centres; in simulated heatwaves, the benefits were short-lived. That is not evidence of no benefit.","label":"Dearman et al., UKHSA, 2025: public health effectiveness of cooling centres, a systematic review","url":"https://researchportal.ukhsa.gov.uk/en/publications/public-health-effectiveness-of-cooling-centres-during-periods-of-/"}],"v":"252"};
